import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.jupiter.api.Test;

class OrderServiceTest {

    // 30 days before this is 2026-10-01 13:00 in Warsaw (CET, UTC+1), that is 11:00Z.
    private static final Instant NOW = Instant.parse("2026-10-31T12:00:00Z");
    private static final Clock CLOCK = Clock.fixed(NOW, ZoneOffset.UTC);

    @Test
    void expireStaleCancelsOnlyPlacedOrdersOlderThan30Days() {
        OrderRepository repository = new OrderRepository();
        OrderService service = new OrderService(repository, CLOCK);

        String oldPlaced = service.place("c-1", Money.pln(100), Instant.parse("2026-09-30T10:00:00Z"));
        String recentPlaced = service.place("c-2", Money.pln(100), Instant.parse("2026-10-02T10:00:00Z"));
        String oldConfirmed = service.place("c-3", Money.pln(100), Instant.parse("2026-09-01T10:00:00Z"));
        service.confirm(oldConfirmed);
        String oldCancelled = service.place("c-4", Money.pln(100), Instant.parse("2026-09-01T10:00:00Z"));
        service.cancel(oldCancelled);

        int cancelled = service.expireStale();

        assertEquals(1, cancelled);
        assertEquals("CANCELLED", service.summary(oldPlaced).status());
        assertEquals("PLACED", service.summary(recentPlaced).status());
        assertEquals("CONFIRMED", service.summary(oldConfirmed).status());
        assertEquals("CANCELLED", service.summary(oldCancelled).status());
    }

    @Test
    void anOrderExactlyAtTheCutoffIsNotExpired() {
        OrderRepository repository = new OrderRepository();
        OrderService service = new OrderService(repository, CLOCK);

        String atCutoff = service.place("c-1", Money.pln(100), Instant.parse("2026-10-01T11:00:00Z"));

        assertEquals(0, service.expireStale());
        assertEquals("PLACED", service.summary(atCutoff).status());
    }

    @Test
    void expireStaleReturnsZeroWhenNothingIsStale() {
        OrderService service = new OrderService(new OrderRepository(), CLOCK);

        assertEquals(0, service.expireStale());
    }
}
}

